                axis = ('v', c)
                break
    if axis is None:
        return out

    typ, p = axis
    # The non-background shape slides toward the solid line, preserving its
    # shape and color. A perpendicular 8 stripe is placed just behind it.
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
